16	interface ProfileEditorProps {
17	  user: CurrentUser;
18	  /** setup: short steps after first signup/login, each step saved. edit: Me editing with one save. */
19	  mode: 'setup' | 'edit';
20	  variant: ABVariant;
21	  showVariantLabel?: boolean;
22	  initialStep?: ProfileStep;
23	  previewOf: (patch: ProfilePatch) => PublicUserProfile;
24	  onCommit: (patch: ProfilePatch) => void;
25	  onClose: () => void;
26	  onDone: () => void;
27	}
