29	export function ProfileEditor({ user, mode, variant, showVariantLabel, initialStep, previewOf, onCommit, onClose, onDone }: ProfileEditorProps) {
30	  const [step, setStep] = useState<SetupStep>(initialStep || 'photo');
31	  const [hobbies, setHobbies] = useState<string[]>(user.hobbies || []);
32	  const [traits, setTraits] = useState<string[]>(user.traits || []);
33	  const [bio, setBio] = useState(user.bio || '');
34	  const [neighborhood, setNeighborhood] = useState(user.neighborhood || NEIGHBORHOOD_OPTIONS[0]);
35	  const [pendingPhoto, setPendingPhoto] = useState<string | null>(null);
