125	            </button>
126	          </section>
127	          {expanded && <div id={detailsId} className="space-y-4">
128	            <section className="bg-white rounded-3xl p-5"><h3 className="text-sm font-bold mb-2">나의 성향</h3><Chips values={profile.traits} empty="아직 등록된 정보가 없어요." /></section>
129	            <section className="bg-white rounded-3xl p-5"><h3 className="text-sm font-bold mb-3">받은 동행 후기 <span className="text-[#6c2cf5]">{profile.reviews.length}</span></h3><Reviews profile={profile} /></section>
130	          </div>}
131	        </> : <>
132	          {header}
133	          <section className="bg-white rounded-3xl p-5"><h3 className="text-sm font-bold mb-2">자기소개</h3><p className="text-sm text-gray-600 leading-relaxed whitespace-pre-wrap">{profile.bio || '아직 자기소개를 작성하지 않았어요.'}</p></section>
134	          <section className="bg-white rounded-3xl p-5 space-y-4">
135	            <div><h3 className="text-sm font-bold mb-2">관심사와 취미</h3><Chips values={profile.hobbies} empty="아직 등록된 정보가 없어요." /></div>
136	            <div><h3 className="text-sm font-bold mb-2">나의 성향</h3><Chips values={profile.traits} empty="아직 등록된 정보가 없어요." /></div>
137	          </section>
138	          <section className="bg-white rounded-3xl p-5"><h3 className="text-sm font-bold mb-3">받은 동행 후기 <span className="text-[#6c2cf5]">{profile.reviews.length}</span></h3><p data-review-summary className="text-xs text-gray-500 mb-1">{reviewSummary}</p><Reviews profile={profile} /></section>
139	        </>}
140	        {!profile.isSample && profile.sugarContent !== null && <p className="text-[11px] text-gray-400">당도 합산·하한·갱신 시점은 논의 중이라 자동으로 바뀌지 않아요.</p>}
141	        {actionBar}
142	      </div>
143	    </div>
144	  </div>;
145	}
