1	import React, { useEffect, useRef, useState } from 'react';
2	
3	const REPORT_REASONS = ['불쾌한 언행·비매너', '금전 요구·영업·포교', '허위 프로필', '연락처 요구·외부 유도', '기타'];
4	
5	function Shell({ label, children, onClose }: { label: string; children: React.ReactNode; onClose: () => void }) {
6	  const ref = useRef<HTMLDivElement>(null);
7	  useEffect(() => {
8	    const previous = document.activeElement as HTMLElement | null;
9	    ref.current?.querySelector<HTMLElement>('input, textarea, button')?.focus();
10	    return () => previous?.focus();
11	  }, []);
12	  return <div role="dialog" aria-modal="true" aria-label={label} className="fixed inset-0 z-[70] bg-black/50 flex items-end sm:items-center justify-center p-0 sm:p-4"
13	    onKeyDown={event => { if (event.key === 'Escape') { event.stopPropagation(); onClose(); } }}>
14	    <div ref={ref} className="bg-white w-full max-w-[400px] rounded-t-3xl sm:rounded-3xl p-5 space-y-3 text-left text-sm">{children}</div>
15	  </div>;
16	}
17	
18	/** Short report entry. The receipt is a prototype example: nothing is sent and no sanction is applied. */
19	export function ReportUserDialog({ targetName, onClose, onSubmit }: { targetName: string; onClose: () => void; onSubmit: (reason: string, detail: string) => void }) {
20	  const [reason, setReason] = useState('');
21	  const [detail, setDetail] = useState('');
22	  const [error, setError] = useState('');
23	  const submit = () => {
24	    if (!reason) { setError('신고 사유를 선택해 주세요.'); return; }
25	    if (detail.trim().length < 5) { setError('상황을 5자 이상 적어 주세요.'); return; }
26	    if (detail.length > 500) { setError('내용은 500자 이하로 적어 주세요.'); return; }
27	    onSubmit(reason, detail.trim());
28	  };
29	  return <Shell label={`${targetName}님 신고`} onClose={onClose}>
30	    <h2 className="text-base font-bold">{targetName}님 신고</h2>
31	    <fieldset className="space-y-1.5"><legend className="text-xs font-bold mb-1">사유</legend>
32	      {REPORT_REASONS.map(item => <label key={item} className="flex items-center gap-2 text-xs"><input type="radio" name="report-reason" checked={reason === item} onChange={() => { setReason(item); setError(''); }} />{item}</label>)}
33	    </fieldset>
34	    <label className="block text-xs font-bold">상황 설명
35	      <textarea rows={3} value={detail} onChange={event => { setDetail(event.target.value); setError(''); }} className="mt-1 w-full rounded-xl border border-gray-200 p-2.5 text-sm font-normal" />
36	    </label>
37	    {error && <p role="alert" className="text-xs text-rose-600">{error}</p>}
38	    <p className="text-[11px] text-gray-500">체험 화면이라 운영팀·기관에 실제로 전달되지 않고, 상대에게 자동 제재나 당도 감점도 없어요.</p>
39	    <div className="grid grid-cols-2 gap-2"><button type="button" onClick={onClose} className="rounded-xl bg-gray-100 py-2.5 text-xs font-bold">취소</button><button type="button" onClick={submit} className="rounded-xl bg-rose-600 text-white py-2.5 text-xs font-bold">신고 접수(예시)</button></div>
40	  </Shell>;
41	}
42	
